// A task reporting its changelist. Identity is (workspace_id, server_key,
// original_number): the number a submit assigns lands in `number`, so the same
// changelist keeps one row across a renumber.
//
// The three COALESCEd columns are facts a later report may not carry: a report
// made before the Swarm review exists must not unset the review a previous one
// attached, and the same holds for the submit timestamp and the owning task.
func (q *Queries) UpsertP4Changelist(ctx context.Context, arg UpsertP4ChangelistParams) (P4Changelist, error) {
	row := q.db.QueryRow(ctx, upsertP4Changelist,
		arg.WorkspaceID,
		arg.DaemonID,
		arg.ServerKey,
		arg.Port,
		arg.Charset,
		arg.Number,
		arg.OriginalNumber,
		arg.Client,
		arg.P4User,
		arg.Status,
		arg.Description,
		arg.Ticket,
		arg.FilesCount,
		arg.ExclusiveFiles,
		arg.Warnings,
		arg.SwarmReviewID,
		arg.TaskID,
		arg.SubmittedAt,
	)
	var i P4Changelist
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.DaemonID,
		&i.ServerKey,
		&i.Port,
		&i.Charset,
		&i.Number,
		&i.OriginalNumber,
		&i.Client,
		&i.P4User,
		&i.Status,
		&i.Description,
		&i.Ticket,
		&i.FilesCount,
		&i.ExclusiveFiles,
		&i.Warnings,
		&i.SwarmReviewID,
		&i.TaskID,
		&i.SubmittedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
